pub fn find<'a>(items: &[&'a str], query: &str) -> Option<&'a str> {
    items.iter().copied().find(|item| *item == query)
}

files.src/search.rs:
pub fn search<'a>(items: &[&'a str], query: &str) -> Vec<&'a str> {
    items.iter().copied().filter(|item| item.contains(query)).collect()
}

